        """Check if function has exactly 1 positional arg AND keyword-only args."""
        spec = inspect.signature(func)
        params = list(spec.parameters.values())
        pos_count = sum(1 for p in params if p.kind in (p.POSITIONAL_ONLY, p.POSITIONAL_OR_KEYWORD))
        kwonly_count = sum(1 for p in params if p.kind == p.KEYWORD_ONLY)
        return pos_count == 1 and kwonly_count > 0


