def get_kwonly_argnames(func):
    """Get names of keyword-only arguments."""
    func = getattr(func, '__original__', None) or unwrap(func)
    if PY2:
        return []
    try:
        sig = inspect.signature(func)
        return [name for name, param in sig.parameters.items() 
                if param.kind == inspect.Parameter.KEYWORD_ONLY]
    except (ValueError, TypeError):
        return []

def arggetter(func, _cache={}):
    if func in _cache:
        return _cache[func]

    original = getattr(func, '__original__', None) or unwrap(func)
    argnames = get_argnames(original)
    kwonly_argnames = get_kwonly_argnames(original)
    all_argnames = argnames + kwonly_argnames

    indexes = dict((name, i) for i, name in enumerate(argnames))
    defaults_tuple = original.__defaults__
    kwonly_defaults = {}

    if not PY2:
        try:
            sig = inspect.signature(original)
            for name, param in sig.parameters.items():
                if param.kind == inspect.Parameter.KEYWORD_ONLY and param.default is not inspect.Parameter.empty:
                    kwonly_defaults[name] = param.default
        except (ValueError, TypeError):
            pass

    if defaults_tuple:
        defaults = dict(zip(argnames[-len(defaults_tuple):], defaults_tuple))
    else:
        defaults = {}

    def get_arg(name, args, kwargs):
        if name not in indexes and name not in kwonly_defaults:
            raise TypeError("%s() doesn't have argument named %s" % (func.__name__, name))
        elif name in indexes:
            index = indexes[name]
            if index < len(args):
                return args[index]
            elif name in kwargs:
                return kwargs[name]
            elif name in defaults:
                return defaults[name]
            else:
                raise TypeError("%s() missing required argument: '%s'" % (func.__name__, name))
        else:
            # It's a keyword-only argument
            if name in kwargs:
                return kwargs[name]
            elif name in kwonly_defaults:
                return kwonly_defaults[name]
            else:
                raise TypeError("%s() missing required argument: '%s'" % (func.__name__, name))

    _cache[func] = get_arg
    return get_arg

